func TestPickReplacementSkipsAssigned(t *testing.T) {
	jobs := []Job{{Key: "a"}, {Key: "b"}, {Key: "c"}}
	got := PickReplacement(jobs, map[string]bool{"a": true, "b": true})
	if got == nil || got.Key != "c" {
		t.Fatalf("got %#v", got)
	}
